import { ChangeDetectionStrategy, Component, input, computed, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ReactiveFormsModule, FormControl } from '@angular/forms';
import { MatIconModule } from '@angular/material/icon';

@Component({
  selector: 'app-input',
  imports: [CommonModule, ReactiveFormsModule, MatIconModule],
  templateUrl: './input.component.html',
  styleUrl: './input.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class InputComponent {
  readonly label = input('');
  readonly type = input('text');
  readonly placeholder = input('');
  readonly icon = input<string | undefined>(undefined);
  readonly control = input<FormControl>(new FormControl());

  readonly isFocused = signal(false);

  get errorMessage(): string {
    const ctrl = this.control();
    if (ctrl.invalid && (ctrl.dirty || ctrl.touched)) {
      if (ctrl.hasError('required')) return 'This field is required';
      if (ctrl.hasError('email')) return 'Invalid email address';
      if (ctrl.hasError('minlength')) return `Minimum ${ctrl.errors?.['minlength'].requiredLength} characters`;
      if (ctrl.hasError('pattern')) {
        if (this.type() === 'password') {
          return 'Must contain uppercase, lowercase, number and special char (@#$%^&+=!?)';
        }
        return 'Invalid format';
      }
    }
    return '';
  }

  onFocus() {
    this.isFocused.set(true);
  }

  onBlur() {
    this.isFocused.set(false);
    this.control().markAsTouched();
  }
}

import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';
import { Router, RouterLink } from '@angular/router';
import { AuthLayoutComponent } from '../../../shared/layouts/auth-layout/auth-layout.component';
import { InputComponent } from '../../../shared/components/input/input.component';
import { ButtonComponent } from '../../../shared/components/button/button.component';
import { AuthHttpService } from '../../../core/services/auth-http.service';
import { AuthStoreService } from '../../../core/services/auth-store.service';
import { MatSnackBar, MatSnackBarModule } from '@angular/material/snack-bar';

@Component({
  selector: 'app-login',
  imports: [
    CommonModule,
    ReactiveFormsModule,
    RouterLink,
    AuthLayoutComponent,
    InputComponent,
    ButtonComponent,
    MatSnackBarModule
  ],
  templateUrl: './login.component.html',
  styleUrl: './login.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class LoginComponent {
  private readonly fb = inject(FormBuilder);
  private readonly authHttp = inject(AuthHttpService);
  private readonly authStore = inject(AuthStoreService);
  private readonly router = inject(Router);
  private readonly snackBar = inject(MatSnackBar);

  readonly isLoading = signal(false);

  readonly loginForm = this.fb.group({
    email: ['', [Validators.required, Validators.email]],
    password: ['', [Validators.required, Validators.minLength(6)]]
  });

  get emailControl() { return this.loginForm.get('email') as any; }
  get passwordControl() { return this.loginForm.get('password') as any; }

  onSubmit() {
    if (this.loginForm.invalid) return;

    this.isLoading.set(true);
    const { email, password } = this.loginForm.value;

    this.authHttp.login({ username: email!, password: password! }).subscribe({
      next: (res) => {
        if (res?.user) {
          this.authStore.setAuthenticatedUser(res.user);
          this.isLoading.set(false);
          this.router.navigate(['/dashboard']);
        } else {
          this.authStore.fetchUser().subscribe({
            next: () => {
              this.isLoading.set(false);
              this.router.navigate(['/dashboard']);
            },
            error: (err: any) => {
              this.isLoading.set(false);
              this.snackBar.open(err.error?.message || 'Error fetching user session', 'Close', { duration: 3000 });
            }
          });
        }
      },
      error: (err) => {
        this.isLoading.set(false);
        this.snackBar.open(err.error?.message || 'Invalid credentials', 'Close', { duration: 3000 });
      }
    });
  }
}

import { ChangeDetectionStrategy, Component, ElementRef, input, output, signal, ViewChildren, QueryList, AfterViewInit } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-otp-input',
  imports: [CommonModule],
  templateUrl: './otp-input.component.html',
  styleUrl: './otp-input.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class OtpInputComponent implements AfterViewInit {
  readonly length = input(6);
  readonly hasError = input(false);
  readonly disabled = input(false);
  readonly codeComplete = output<string>();

  readonly digits = signal<string[]>(['', '', '', '', '', '']);
  readonly focusedIndex = signal<number>(-1);

  @ViewChildren('digitInput') digitInputs!: QueryList<ElementRef<HTMLInputElement>>;

  ngAfterViewInit() {
    // Auto-focus first input
    setTimeout(() => this.focusInput(0), 100);
  }

  onInput(index: number, event: Event) {
    const input = event.target as HTMLInputElement;
    let value = input.value.toUpperCase(); // Backend accepts A-Z0-9

    // Only allow alphanumeric
    value = value.replace(/[^A-Z0-9]/g, '');

    if (value.length > 1) {
      // Handle multi-character input (e.g., autocomplete)
      value = value[0];
    }

    const newDigits = [...this.digits()];
    newDigits[index] = value;
    this.digits.set(newDigits);
    input.value = value;

    if (value && index < this.length() - 1) {
      this.focusInput(index + 1);
    }

    this.checkComplete();
  }

  onKeyDown(index: number, event: KeyboardEvent) {
    if (event.key === 'Backspace') {
      const currentDigits = this.digits();
      if (!currentDigits[index] && index > 0) {
        // Current is empty, go back to previous
        event.preventDefault();
        const newDigits = [...currentDigits];
        newDigits[index - 1] = '';
        this.digits.set(newDigits);
        this.focusInput(index - 1);
      } else {
        // Clear current
        const newDigits = [...currentDigits];
        newDigits[index] = '';
        this.digits.set(newDigits);
      }
    } else if (event.key === 'ArrowLeft' && index > 0) {
      event.preventDefault();
      this.focusInput(index - 1);
    } else if (event.key === 'ArrowRight' && index < this.length() - 1) {
      event.preventDefault();
      this.focusInput(index + 1);
    }
  }

  onPaste(event: ClipboardEvent) {
    event.preventDefault();
    const pasteData = event.clipboardData?.getData('text')?.toUpperCase().replace(/[^A-Z0-9]/g, '') || '';

    if (pasteData.length === 0) return;

    const newDigits = [...this.digits()];
    for (let i = 0; i < Math.min(pasteData.length, this.length()); i++) {
      newDigits[i] = pasteData[i];
    }
    this.digits.set(newDigits);

    // Focus the next empty input or the last one
    const nextEmpty = newDigits.findIndex(d => !d);
    this.focusInput(nextEmpty >= 0 ? nextEmpty : this.length() - 1);

    // Update all input element values
    setTimeout(() => {
      this.digitInputs.forEach((input, i) => {
        input.nativeElement.value = newDigits[i];
      });
    });

    this.checkComplete();
  }

  onFocus(index: number) {
    this.focusedIndex.set(index);
    // Select the content of the focused input
    const input = this.digitInputs?.get(index)?.nativeElement;
    if (input) input.select();
  }

  onBlur() {
    this.focusedIndex.set(-1);
  }

  reset() {
    this.digits.set(Array(this.length()).fill(''));
    this.digitInputs?.forEach(input => {
      input.nativeElement.value = '';
    });
    setTimeout(() => this.focusInput(0), 50);
  }

  private focusInput(index: number) {
    const input = this.digitInputs?.get(index)?.nativeElement;
    if (input) input.focus();
  }

  private checkComplete() {
    const code = this.digits().join('');
    if (code.length === this.length() && code.split('').every(d => d !== '')) {
      this.codeComplete.emit(code);
    }
  }
}

import { ChangeDetectionStrategy, Component, inject, signal, OnDestroy, OnInit, ViewChild } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { AuthLayoutComponent } from '../../../shared/layouts/auth-layout/auth-layout.component';
import { OtpInputComponent } from '../../../shared/components/otp-input/otp-input.component';
import { AuthHttpService } from '../../../core/services/auth-http.service';
import { AuthStoreService } from '../../../core/services/auth-store.service';
import { RegistrationStateService } from '../../../core/services/registration-state.service';
import { MatSnackBar, MatSnackBarModule } from '@angular/material/snack-bar';
import { MatIconModule } from '@angular/material/icon';
import { MatProgressSpinnerModule } from '@angular/material/progress-spinner';

@Component({
  selector: 'app-otp-verify',
  imports: [
    CommonModule,
    AuthLayoutComponent,
    OtpInputComponent,
    MatSnackBarModule,
    MatIconModule,
    MatProgressSpinnerModule
  ],
  templateUrl: './otp-verify.component.html',
  styleUrl: './otp-verify.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class OtpVerifyComponent implements OnInit, OnDestroy {
  private readonly authHttp = inject(AuthHttpService);
  private readonly authStore = inject(AuthStoreService);
  private readonly registrationState = inject(RegistrationStateService);
  private readonly router = inject(Router);
  private readonly snackBar = inject(MatSnackBar);

  readonly isLoading = signal(false);
  readonly isResending = signal(false);
  readonly isSuccess = signal(false);
  readonly resendCooldown = signal(60);
  readonly hasError = signal(false);

  readonly maskedUsername = this.registrationState.maskedUsername;

  @ViewChild(OtpInputComponent) otpInput!: OtpInputComponent;

  private cooldownTimer?: ReturnType<typeof setInterval>;

  ngOnInit() {
    if (!this.registrationState.hasActiveRegistration()) {
      this.snackBar.open('Registration session expired. Please register again.', 'Close', { duration: 5000 });
      this.router.navigate(['/auth/register']);
      return;
    }
    this.startCooldown();
  }

  ngOnDestroy() {
    if (this.cooldownTimer) clearInterval(this.cooldownTimer);
  }

  private startCooldown() {
    this.resendCooldown.set(60);
    if (this.cooldownTimer) clearInterval(this.cooldownTimer);
    this.cooldownTimer = setInterval(() => {
      this.resendCooldown.update(v => v > 0 ? v - 1 : 0);
      if (this.resendCooldown() === 0 && this.cooldownTimer) {
        clearInterval(this.cooldownTimer);
      }
    }, 1000);
  }

  onCodeComplete(code: string) {
    this.verifyCode(code);
  }

  private verifyCode(code: string) {
    const userId = this.registrationState.userId();
    if (!userId) return;

    this.isLoading.set(true);
    this.hasError.set(false);

    this.authHttp.verifyCode({ userId, code }).subscribe({
      next: () => {
        // Verification successful — attempt auto-login
        this.autoLogin();
      },
      error: (err) => {
        this.isLoading.set(false);
        this.hasError.set(true);
        // Reset OTP input after a brief delay so the error animation plays
        setTimeout(() => {
          this.otpInput?.reset();
          this.hasError.set(false);
        }, 600);
        this.snackBar.open(
          err.error?.message || 'Incorrect or expired code. Please try again.',
          'Close',
          { duration: 4000 }
        );
      }
    });
  }

  private autoLogin() {
    const username = this.registrationState.username();
    const password = this.registrationState.getPasswordForAutoLogin();

    if (!username || !password) {
      // Password was lost (page refresh) — fallback to login page
      this.isLoading.set(false);
      this.registrationState.clear();
      this.snackBar.open('Account verified successfully! Please log in.', 'Close', { duration: 5000 });
      this.router.navigate(['/auth/login']);
      return;
    }

    this.authHttp.login({ username, password }).subscribe({
      next: () => {
        this.authStore.fetchUser().subscribe({
          next: () => {
            this.isLoading.set(false);
            this.isSuccess.set(true);
            this.registrationState.clear();

            // Show success animation for 2.5 seconds, then navigate
            setTimeout(() => {
              this.router.navigate(['/dashboard']);
            }, 2500);
          },
          error: () => {
            this.fallbackToLogin();
          }
        });
      },
      error: () => {
        this.fallbackToLogin();
      }
    });
  }

  private fallbackToLogin() {
    this.isLoading.set(false);
    this.registrationState.clear();
    this.snackBar.open('Account verified! Please log in to continue.', 'Close', { duration: 5000 });
    this.router.navigate(['/auth/login']);
  }

  resendCode() {
    const userId = this.registrationState.userId();
    if (!userId || this.resendCooldown() > 0) return;

    this.isResending.set(true);
    this.authHttp.refreshCode(userId).subscribe({
      next: () => {
        this.isResending.set(false);
        this.snackBar.open('A new code has been sent!', 'Close', { duration: 3000 });
        this.startCooldown();
        this.otpInput?.reset();
      },
      error: (err) => {
        this.isResending.set(false);
        this.snackBar.open(err.error?.message || 'Error resending code. Please wait and try again.', 'Close', { duration: 4000 });
      }
    });
  }
}

