src/app/core/interceptors/auth.intercept.defaultValue:
(req, next) => {
  const apiBaseUrl = 'http://localhost:8080/api';

  if (req.url.startsWith(apiBaseUrl) || req.url.startsWith('/api')) {
    const clonedRequest = req.clone({
      withCredentials: true
    });
    return next(clonedRequest);
  }

  return next(req);
}

src/app/core/interceptors/error.intercep.defaultValue:
(req, next) => {
  const router = inject(Router);

  return next(req).pipe(
    catchError((error: HttpErrorResponse) => {
      if ([401, 403].includes(error.status)) {
        // Redirect to login if unauthorized
        // The AuthStoreService will handle state cleanup
        router.navigate(['/auth/login']);
      }
      return throwError(() => error);
    })
  );
}

